func (q *Queries) ListAdminCancellationFollowers(ctx context.Context, arg ListAdminCancellationFollowersParams) ([]AdminOperation, error) {
	rows, err := q.db.Query(ctx, listAdminCancellationFollowers, arg.RootID, arg.BatchLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminOperation{}
	for rows.Next() {
		var i AdminOperation
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ActorKind,
			&i.ActorID,
			&i.ActorAuthVersion,
			&i.TargetKind,
			&i.TargetID,
			&i.Kind,
			&i.IdempotencyKey,
			&i.PayloadHash,
			&i.Reason,
			&i.State,
			&i.ResultCode,
			&i.Version,
			&i.Confirmation,
			&i.ReconciliationState,
			&i.TargetInstallationID,
			&i.TargetTaskID,
			&i.BindingID,
			&i.BindingEpoch,
			&i.ExecutionFence,
			&i.RootOperationID,
			&i.AckDeadline,
			&i.AcceptedAt,
			&i.AppliedAt,
			&i.ConfirmedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ExecutionRuntimeID,
			&i.ExecutionDispatchedAt,
			&i.NextReconcileAt,
			&i.EffectsCompletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

